WITH lines AS (SELECT id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) x AS elem) SELECT product_id, DATE_TRUNC('DAY', created_at) AS activity_day, DATE_TRUNC('HOUR', created_at) AS hour_window, COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END) AS welcome5_count, COUNT_IF(promo = 'VIP') AS vip_events, MIN(created_at) AS started_at, COUNT(*) FILTER (WHERE promo = 'VIP') AS vip_rows, COUNT(DISTINCT promo) AS distinct_promos, COUNT(DISTINCT promo) AS distinct_promos_2 FROM lines GROUP BY ROLLUP (product_id, DATE_TRUNC('DAY', created_at), DATE_TRUNC('HOUR', created_at))
